Thanks for your answer Chris. In first i used this function

re <- robustness(g, type = c('vertex'), measure = c('random'), N = 100)

but the result is one. i found this other code for the function, and not run but no show fails:

library(igraph)
library(brainGraph)
d <- read.csv(file.choose(),header=TRUE)
g <- graph.data.frame(d, directed=FALSE)
robustness <- function(g, type=c('vertex'),
                       measure=c('random'), N=100) {
  stopifnot(is_igraph(g))
  type <- match.arg(type)
  measure <- match.arg(measure)
  max.comp.orig <- g$max.comp
  if (type == 'vertex') {
    n <- vcount(g)

    if (measure == 'random') {
      max.comp <- matrix(nrow=n+1, ncol=N)
      max.comp <- foreach(i=seq_len(N), .combine='rbind') %dopar% {
        g.new <http://g.new> <- g
        ord <- V(g.new <http://g.new>)$name[sample(n)]
        tmp <- vector('integer', length=n)
        for (j in seq_len(n - 1)) {
          g.new <http://g.new> <- delete.vertices(g.new <http://g.new>, ord[j])
          tmp[j] <- max(components(g.new <http://g.new>)$csize)
        }
        tmp
      }
      max.comp <- cbind(1, max.comp)
      max.comp.removed <- colMeans(max.comp)

    } else {
      ord <- V(g)$name[order(vertex_attr(g, measure), decreasing=TRUE)]
      max.comp.removed <- vector('integer', length=n+1)
      max.comp.removed[1] <- 1
      for (i in seq_len(n - 1)) {
        g <- delete.vertices(g, ord[i])
        max.comp.removed[i+1] <- max(components(g)$csize)
      }
    }

  } else {
    m <- ecount(g)
    if (measure == 'degree') {
      stop('For edge attacks, must choose "btwn.cent" or "random"!')
    } else if (measure == 'random') {
      max.comp <- matrix(nrow=m+1, ncol=N)
      max.comp <- foreach(i=seq_len(N), .combine='rbind') %dopar% {
        g.new <http://g.new> <- g
        ord <- sample(m)
        verts <- as_edgelist(g.new <http://g.new>)[ord, ]
        tmp <- vector('integer', length=m)
        for (j in seq_along(ord)) {
          g.new <http://g.new> <- delete.edges(g.new <http://g.new>, E(g.new <http://g.new>)[verts[ord[j], 1] %--% verts[ord[j], 2]])
          tmp[j] <- max(components(g.new <http://g.new>)$csize)
        }
        tmp
      }
      max.comp <- cbind(1, max.comp)
      max.comp.removed <- colMeans(max.comp)

    } else {
      ord <- order(E(g)$btwn, decreasing=TRUE)
      verts <- as_edgelist(g)[ord, ]
      max.comp.removed <- vector('integer', length=m+1)
      max.comp.removed[1] <- 1
      for (i in seq_along(ord)) {
        g <- delete.edges(g, E(g)[verts[ord[i], 1] %--% verts[ord[i], 2]])
        max.comp.removed[i+1] <- max(components(g)$csize)
      }
    }

  }
  comp.ratio <- c(max.comp.removed[1], max.comp.removed[-1] / max.comp.orig)
  return(comp.ratio)

}

